<script setup lang="ts">
import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage,type FormInstance,type FormRules } from 'element-plus'; import { apiError } from '../api'; import { useAuthStore } from '../stores'
const formRef=ref<FormInstance>(); const loading=ref(false); const form=reactive({name:'',email:'',password:'',confirm:''}); const auth=useAuthStore(); const router=useRouter()
const rules:FormRules={name:[{required:true,message:'请输入姓名',trigger:'blur'}],email:[{required:true,message:'请输入邮箱',trigger:'blur'},{type:'email',message:'邮箱格式不正确',trigger:'blur'}],password:[{required:true,message:'请输入密码',trigger:'blur'},{min:8,message:'密码至少 8 位',trigger:'blur'}],confirm:[{validator:(_:unknown,v:string,done:(e?:Error)=>void)=>v===form.password?done():done(new Error('两次密码不一致')),trigger:'blur'}]}
async function submit(){if(!await formRef.value?.validate())return;loading.value=true;try{await auth.register({name:form.name,email:form.email,password:form.password});ElMessage.success('注册成功');if(auth.isAuthenticated)router.push('/');else router.push('/login')}catch(e){ElMessage.error(apiError(e,'注册失败'))}finally{loading.value=false}}
</script>
<template><div class="register-page"><router-link to="/login" class="brand"><span>R</span>RobotCare AI</router-link><div class="card panel"><p class="eyebrow">CREATE ACCOUNT</p><h1>创建账户</h1><p>保存你的设备、诊断进度与售后报告</p><el-form ref="formRef" :model="form" :rules="rules" label-position="top" size="large"><el-form-item label="姓名" prop="name"><el-input v-model="form.name" placeholder="如何称呼你" /></el-form-item><el-form-item label="邮箱" prop="email"><el-input v-model="form.email" placeholder="name@example.com" /></el-form-item><div class="twocol"><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" show-password /></el-form-item><el-form-item label="确认密码" prop="confirm"><el-input v-model="form.confirm" type="password" show-password /></el-form-item></div><el-alert title="注册即表示你了解：本产品是独立第三方辅助工具，不替代官方维修服务。" type="info" :closable="false" show-icon/><el-button class="brand-button" type="primary" :loading="loading" @click="submit">注册并开始使用</el-button></el-form><p class="switch">已有账户？<router-link to="/login">返回登录</router-link></p></div></div></template>
<style scoped>.register-page{min-height:100vh;background:radial-gradient(circle at 20% 10%,#dcf5eb,transparent 30%),#f4f7f6;padding:35px;display:flex;flex-direction:column}.brand{font-size:19px;font-weight:750;display:flex;gap:10px;align-items:center}.brand span{display:grid;place-items:center;width:34px;height:34px;background:var(--brand);color:#fff;border-radius:10px}.card{width:560px;margin:auto;padding:42px 46px}.card h1{margin:12px 0 7px}.card>p:not(.eyebrow){color:var(--muted);margin:0 0 28px}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:16px}.brand-button{width:100%;margin-top:22px}.switch{text-align:center!important;margin:20px 0 0!important;font-size:14px}.switch a{color:var(--brand);font-weight:700}</style>
